code.java:
class Solution {
    public int[] findDoubleBooked(int[] bookings) {
        int n = bookings.length;
        List<Integer> out = new ArrayList<>();
        for (int x = 1; x <= n; x++) {
            int c = 0;
            for (int v : bookings) if (v == x) c++;
            if (c == 2) out.add(x);
        }
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

