class Solution:
    def findDoubleBooked(self, bookings: List[int]) -> List[int]:
        n = len(bookings)
        for i in range(n):
            v = (bookings[i] - 1) % n + 1
            bookings[v - 1] += n
        twice = []
        for i in range(n):
            if bookings[i] > 2 * n:
                twice.append(i + 1)
            bookings[i] = (bookings[i] - 1) % n + 1
        return twice

